import{z as l,x as i,o as A,c as d,q as n,j as r,D as e,d as B,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"TAQ 数据处理","description":"","frontmatter":{"title":"TAQ 数据处理","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/taq-processing.md","filePath":"quant/taq-processing.md","lastUpdated":1791413859000}'),p={name:"quant/taq-processing.md"};function u(T,a,c,m,h,D){const t=i("Mermaid");return A(),d("div",null,[a[2]||(a[2]=n('<h1 id="taq-数据处理" tabindex="-1">TAQ 数据处理 <a class="header-anchor" href="#taq-数据处理" aria-label="Permalink to &quot;TAQ 数据处理&quot;">​</a></h1><div class="epigraph"><p>TAQ 是 SIP 磁带上的报价与成交，不是撮合核的 L3。清洗规则决定你看见的价差与不平衡；Holden 与 Jacobsen 把这些规则写成可重复的研究步骤。</p><footer>—— Holden and Jacobsen, Liquidity Measurement Problems in Fast, Competitive Markets: Expensive and Cheap Solutions, JFQA, 2014；Hasbrouck 对 TAQ 与微观结构度量的讨论</footer></div><p><a href="/quant/crsp-compustat">上一课</a>把日频身份对齐。<a href="/quant/l2-l3-data">L2/L3</a>与<a href="/quant/sip-vs-direct">SIP</a>已说明 TAQ 通常是汇总统带。本课的缺口是<strong>日度微观结构度量如何从脏磁带算出来</strong>：时间戳、撤消、锁定交叉、盘前盘后、与 NBBO 构造。Holden 与 Jacobsen（2014）表明：在高速竞争市场上，廉价的日度近似与昂贵的逐笔清洗会得到不同的流动性结论。后课基本面重述换对象；本课不重建 ITCH 式队列——那是<a href="/quant/orderbook-reconstruction">订单簿重建</a>的直连问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原始 TAQ（或日度 TAQ）含：条件成交、修正、异常报价、毫秒碰撞、跨所不同步。直接用「每笔成交对当时报价」算有效价差，会把锁定/交叉、过时报价、非正规成交算进去，价差被系统性扭曲。问题是声明清洗清单，并承认清单是识别假设：滤掉的是噪声还是真实压力，会改变危机日的结论。</p><p>NBBO 必须从各所报价合成，且受保护报价规则约束。用单一交易所报价当全国最优，有效价差没有制度含义。用已清洗的 NBBO 去标记直连成交，又会混源，见 SIP 课。研究全国执行质量，TAQ/SIP 是对的对象；研究本所队列，TAQ 不够。</p><p><span class="marginnote">术语翻译：NBBO（全国最优买卖报价）是把全美各交易所挂牌汇总后取的「全国最好的买价与卖价」，是量执行质量与有效价差的尺子。拿单一交易所的报价当尺子，量出来的是「那一家所的市场」，不是全国市场。</span></p><h3 id="时间戳粒度改变-lee–ready" tabindex="-1">时间戳粒度改变 Lee–Ready <a class="header-anchor" href="#时间戳粒度改变-lee–ready" aria-label="Permalink to &quot;时间戳粒度改变 Lee–Ready&quot;">​</a></h3><p>成交方向分类依赖成交相对报价的位置。毫秒级碰撞、报价与成交不同步，使「上一笔报价」定义含糊。Holden–Jacobsen 讨论插值与昂贵的逐笔对钟。日度汇总（如 WRDS 的衍生指标）把选择藏进黑箱：便宜、不可审计。论文必须写清：用官方衍生还是自建清洗，规则版本号是什么。</p><p><span class="marginnote">A 股没有 TAQ。对应的是交易所逐笔与行情快照。清洗对象换成：集合竞价、涨跌停锁定、无效申报、盘后定价。原则同构——声明过滤器，不要把原始打印当有效价差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最低清洗：剔除更正与取消、非标准成交条件、明显的价格离群（相对前成交或报价）、锁定交叉报价或不单独处理它们、盘前盘后分段。有效价差、实现价差、报价斜率按 Hasbrouck / Holden–Jacobsen 的定义实现，并报告对过滤阈值的敏感度。按日聚合时声明：等权成交、金额加权、还是仅正规时段。</p><p>与 CRSP 对齐用 PERMNO–CUSIP–日期，注意股票代码复用。停牌日、停牌时段应从流动性样本删除或单列。分钟或更粗的 bar 若从 TAQ 合成，必须定义：最后成交、最后报价、还是微观价格；合成 bar 不能再解释为 L3 事件。</p><h3 id="便宜方案与昂贵方案要并列" tabindex="-1">便宜方案与昂贵方案要并列 <a class="header-anchor" href="#便宜方案与昂贵方案要并列" aria-label="Permalink to &quot;便宜方案与昂贵方案要并列&quot;">​</a></h3><p>Holden–Jacobsen 的标题即结论：有便宜的日度代理，也有贵的逐笔方案，二者在高速市场上差得可见。复制研究应同时报告：若只为截面因子控制「非流动性」，日度代理可能够；若为执行算法校准冲击，必须昂贵方案或直连。把 CRSP 日度买卖价差代理直接当 TAQ 有效价差，是第三种更粗的东西，不能混名。</p><p><span class="marginnote">数字实例：同一批 2010-05-06 闪电崩盘日的成交，保留锁定/交叉报价算出的平均有效价差，与全部剔除后相比可以差出一倍量级——过滤器怎么选，直接决定「那天市场有多贵」的答案。这就是「廉价与昂贵方案要并列报告」的含义：不是精度差一点，而是结论可能相反。</span></p><p>「你手头的问题该走哪条测量路线」可以用一张分诊图回答：</p>',17)),(A(),r(s,null,{default:e(()=>[o(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q1%5B%22%E6%88%AA%E9%9D%A2%E5%9B%A0%E5%AD%90%EF%BC%9A%E5%8F%AA%E8%A6%81%E9%9D%9E%E6%B5%81%E5%8A%A8%E6%80%A7%E6%8E%A7%E5%88%B6%22%5D%20--%3E%20CHEAP%5B%22%E4%BE%BF%E5%AE%9C%EF%BC%9A%E6%97%A5%E5%BA%A6%E4%BB%A3%E7%90%86%EF%BC%88CRSP%20%2F%20WRDS%EF%BC%89%22%5D%0A%20%20Q2%5B%22%E6%89%A7%E8%A1%8C%E7%AE%97%E6%B3%95%EF%BC%9A%E8%A6%81%E5%86%B2%E5%87%BB%E4%B8%8E%E4%BB%B7%E5%B7%AE%E6%A0%A1%E5%87%86%22%5D%20--%3E%20EXP%5B%22%E6%98%82%E8%B4%B5%EF%BC%9A%E9%80%90%E7%AC%94%E6%B8%85%E6%B4%97%20TAQ%20%E6%88%96%E7%9B%B4%E8%BF%9E%22%5D%0A%20%20Q3%5B%22%E8%AE%BA%E6%96%87%EF%BC%9A%E8%A6%81%E5%8F%AF%E5%A4%8D%E7%8E%B0%E7%BB%93%E8%AE%BA%22%5D%20--%3E%20BOTH%5B%22%E4%B8%A4%E6%B3%95%E5%B9%B6%E5%88%97%20%2B%20%E8%BF%87%E6%BB%A4%E5%99%A8%E6%95%8F%E6%84%9F%E5%BA%A6%22%5D%0A%20%20CHEAP%20--%3E%20CAVEAT%5B%22%E4%B8%8D%E5%BE%97%E7%94%A8%E5%BE%AE%E8%A7%82%E7%BB%93%E6%9E%84%E8%AF%AD%E8%A8%80%E8%A7%A3%E8%AF%BB%22%5D%0A%20%20EXP%20--%3E%20AUDIT%5B%22%E6%B8%85%E6%B4%97%E8%A7%84%E5%88%99%E7%89%88%E6%9C%AC%E5%8C%96%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"SIP 汇总延迟使 TAQ 的「当时 NBBO」慢于直连。用它估的价差偏大或方向分类偏误，在 HFT 活跃的名字上更严重。清洗若把锁定交叉全删，等于在压力状态上做选择：2010-05-06 一类日子会被洗成「较干净」的市场。过滤器因此不是中性预处理，是对「什么算市场」的定义。",-1)),a[5]||(a[5]=E("p",null,"日频因子研究用 TAQ 往往只为了构造 Amihud 或价差控制。那是合法降维，但须停止使用微观结构语言（队列、毒性）去描述降维后的对象。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：用 WRDS 日度价差代理做完控制变量，转头又谈「队列」「订单流毒性」——那个数早已降维到日频，任何队列级语言都是过度解释。要谈毒性，请回到逐笔磁带重做。")],-1)),(A(),r(s,null,{default:e(()=>[o(t,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20Raw%5B%22TAQ%20%E5%8E%9F%E5%A7%8B%E6%8A%A5%E4%BB%B7%E4%B8%8E%E6%88%90%E4%BA%A4%22%5D%20--%3E%20Filt%5B%22%E6%9D%A1%E4%BB%B6%20%E4%BF%AE%E6%AD%A3%20%E7%A6%BB%E7%BE%A4%20%E6%97%B6%E6%AE%B5%22%5D%0A%20%20Filt%20--%3E%20NBBO%5B%22%E5%90%88%E6%88%90%20NBBO%22%5D%0A%20%20NBBO%20--%3E%20ES%5B%22%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%20%2F%20%E6%96%B9%E5%90%91%E5%88%86%E7%B1%BB%22%5D%0A%20%20ES%20--%3E%20Day%5B%22%E6%97%A5%E5%BA%A6%E8%81%9A%E5%90%88%22%5D%0A%20%20Day%20--%3E%20Factor%5B%22%E5%9B%A0%E5%AD%90%E6%8E%A7%E5%88%B6%E5%8F%98%E9%87%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>TAQ 许可限制分发。本课不提供整库转载。欧洲、亚洲的官方磁带有各自字段，不能把 Holden–Jacobsen 的美股阈值原样贴上。加密成交回放不是 TAQ。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TAQ 是 SIP 投影；清洗规则是识别假设，须版本化并做敏感度。</li><li>全国执行质量用 NBBO；本所队列用直连重建，不要混用语言。</li><li>便宜日度代理与昂贵逐笔方案回答不同问题。</li><li>出处：Holden and Jacobsen, <em>JFQA</em>, 2014；Hasbrouck。</li></ul>',4))])}const q=l(p,[["render",u]]);export{P as __pageData,q as default};
